'use strict';
const evalCriteria=[['objective','Objetivo e briefing'],['quality','Qualidade e acabamento'],['evidence','Precisão e evidências'],['format','Formato e voz da marca'],['timing','Respeito ao prazo']];
function executionOf(t){if(!t.execution)t.execution={reviewMinutes:Math.max(1,Math.floor(t.minutes*.2)),mode:'sequential',startedAt:null,deadlineAt:null,handoffs:[],evals:[]};return t.execution}
function executionValid(t){const x=t.execution;if(!x)return true;const timestamp=v=>typeof v==='string'&&!Number.isNaN(Date.parse(v));return x&&Number.isInteger(x.reviewMinutes)&&x.reviewMinutes>0&&x.reviewMinutes<=t.minutes&&((x.startedAt===null&&x.deadlineAt===null)||(timestamp(x.startedAt)&&timestamp(x.deadlineAt)&&Date.parse(x.deadlineAt)-Date.parse(x.startedAt)===t.minutes*60000))&&Array.isArray(x.handoffs)&&x.handoffs.length<=3&&new Set(x.handoffs.map(h=>h.agent)).size===x.handoffs.length&&x.handoffs.every(h=>h&&t.creators.includes(h.agent)&&Number.isInteger(h.minutes)&&h.minutes>0&&typeof h.prompt==='string'&&h.prompt.length<=30000)&&(!x.mode||['sequential','parallel'].includes(x.mode))&&(x.mode==='parallel'?Math.max(0,...x.handoffs.map(h=>h.minutes)):x.handoffs.reduce((a,h)=>a+h.minutes,0))+x.reviewMinutes<=t.minutes&&Array.isArray(x.evals)&&x.evals.length<=100&&x.evals.every(e=>e&&typeof e.agent==='string'&&(e.agent===t.director||t.creators.includes(e.agent))&&typeof e.comment==='string'&&e.comment.length<=10000&&typeof e.evidence==='string'&&e.evidence.length>0&&e.evidence.length<=10000&&timestamp(e.createdAt)&&evalCriteria.every(([k])=>Number.isInteger(e.scores?.[k])&&e.scores[k]>=0&&e.scores[k]<=5))}
function evalsComplete(t){const x=t.execution;return !!x&&Array.isArray(x.evals)&&[t.director,...t.creators].every(id=>x.evals.some(e=>e.agent===id))}
function promptFor(t,id,minutes){const p=person(id),pr=project(t.project);return `Você é ${p.name}, ${p.role}, e trabalha sob a direção de ${person(t.director).name} nesta tarefa específica.\n\nOBJETIVO\n${t.brief}\n\nMATERIAL ESPERADO\n${t.format}\n\nMARCA E PÚBLICO\n${pr.name}: ${pr.description}\nPúblico: ${pr.audience||'Não informado; sinalize se essencial.'}\nTom de voz: ${pr.tone||'A definir com a diretora.'}\nOrientações: ${pr.notes}\n\nSEU REPERTÓRIO\n${p.skills}\n${p.instructions}\nJeito de trabalhar: ${p.personality}\n\nDIREÇÃO DESTA RODADA\n${t.plan||'A diretora deve especificar aqui a sua parte da entrega antes da execução.'}\n\nORÇAMENTO DE TEMPO\nA tarefa inteira tem ${durationLabel(t.minutes)}; sua parte tem no máximo ${durationLabel(minutes)}. Seu repasse deve voltar dentro do prazo global, preservando a revisão da diretora. Se houver prazo absoluto registrado: ${t.execution?.deadlineAt?dateLabel(t.execution.deadlineAt):'consultar o início da janela de trabalho'}. Não reinicie o prazo ao receber ou repassar trabalho.\n\nCONTRATO DE ENTREGA\nDevolva material utilizável, uma explicação curta das decisões, fontes ou evidências para afirmações factuais, pendências e sugestões de revisão. Não invente fatos, dados, fontes ou execução de ferramentas. Se faltar ferramenta, peça à diretora com necessidade, custo e impacto no prazo; aguarde a autorização do usuário.\n\nAVALIAÇÃO\nSeu trabalho será avaliado em objetivo, qualidade, precisão, formato e prazo. A diretora deve avaliar a entrega e solicitar correções no tempo restante. Não se atribua uma nota de sucesso sem evidências.`}
function qualityForm(id){const t=taskById(id),x=executionOf(t);const defaultMinutes=Math.max(1,Math.floor((t.minutes-x.reviewMinutes)/Math.max(t.creators.length,1)));const body=`<div class="deadline-contract"><span class="eyebrow">UM ÚNICO PRAZO</span><h3>${durationLabel(t.minutes)} para a entrega completa</h3><p>Os repasses e as avaliações cabem nesta janela. Pedidos de ferramentas não reiniciam o tempo.</p>${x.deadlineAt?`<strong>Limite: ${esc(dateLabel(x.deadlineAt))}</strong>`:'<small>A janela ainda não foi iniciada.</small>'}</div>${selectField('mode','Como os criadores trabalham?',x.mode||'sequential',[['sequential','Em sequência · há dependências'],['parallel','Em paralelo · entregas independentes']])}<label class="field"><span>Tempo reservado à revisão da diretora (minutos)</span><input name="review" type="number" min="1" max="${t.minutes}" value="${x.reviewMinutes}" required></label>${t.creators.length?t.creators.map(id=>{const p=person(id),h=x.handoffs.find(h=>h.agent===id);return `<section class="handoff-form"><div class="lead-profile"><img src="${personImage(p)}" alt=""><div><span class="eyebrow">REPASSE PARA</span><h3>${esc(p.name)}</h3><p>${esc(p.role)}</p></div></div><label class="field"><span>Tempo máximo deste repasse (minutos)</span><input name="time-${esc(id)}" type="number" min="1" max="${t.minutes}" value="${h?.minutes||defaultMinutes}" required></label><label class="field"><span>Instruções específicas desta rodada</span><textarea name="prompt-${esc(id)}" maxlength="30000" rows="10" required>${esc(h?.prompt||promptFor(t,id,h?.minutes||defaultMinutes))}</textarea><small>Rascunho montado com o briefing atual. A diretora deve revisar e personalizar antes de executar.</small></label><button class="btn" type="button" data-quality="refresh-prompt" data-task="${esc(t.id)}" data-agent="${esc(id)}">${ico('spark')}Refazer rascunho com o briefing atual</button></section>`}).join(''):'<p class="form-context">Primeiro registre os criadores escolhidos no Plano da diretora. Ela pode trabalhar sozinha quando a tarefa permitir.</p>'}<div class="delegation-note">${ico('clock')}Em sequência, somamos os repasses. Em paralelo, consideramos o repasse mais longo. A revisão final sempre precisa caber nos ${t.minutes} minutos totais. Use paralelo apenas para entregas independentes.</div>`;studioForm('Repasses, prompts e prazo',t.title,body,fd=>{const reviewMinutes=Number(fd.get('review'));const handoffs=t.creators.map(id=>({agent:id,minutes:Number(fd.get('time-'+id)),prompt:String(fd.get('prompt-'+id)||'').trim()}));if(!Number.isInteger(reviewMinutes)||reviewMinutes<1||handoffs.some(h=>!Number.isInteger(h.minutes)||h.minutes<1||!h.prompt))return {error:'Defina tempos inteiros positivos e instruções para cada criador.'};const mode=fd.get('mode')==='parallel'?'parallel':'sequential';const total=(mode==='parallel'?Math.max(0,...handoffs.map(h=>h.minutes)):handoffs.reduce((a,h)=>a+h.minutes,0))+reviewMinutes;if(total>t.minutes)return {error:`O plano usa ${total} minutos, mas você deu ${t.minutes}. Reduza os repasses e reserve a revisão dentro do prazo.`};x.reviewMinutes=reviewMinutes;x.mode=mode;x.handoffs=handoffs;return {action:'Registrou repasses e prompts: '+t.title}})}
function evalForm(id){const t=taskById(id),x=executionOf(t);studioForm('Avaliação da entrega',t.title,selectField('agent','Perfil avaliado',t.director,[t.director,...t.creators].map(id=>[id,person(id).name+' · '+person(id).role]))+`<p class="form-context">Registre uma avaliação baseada em material real. A diretora avalia cada criador; você avalia a entrega da diretora. Escala: 0 = não atende, 5 = atende plenamente.</p>`+evalCriteria.map(([k,label])=>`<label class="field"><span>${label} · 0 a 5</span><input name="${k}" type="number" min="0" max="5" step="1" required placeholder="Nota com base na entrega"></label>`).join('')+field('evidence','Material ou evidência avaliada','','textarea','Cole um trecho, referência ou link para o material real.',true)+field('comment','O que deve melhorar na próxima rodada?','','textarea'),fd=>{const scores=Object.fromEntries(evalCriteria.map(([k])=>[k,Number(fd.get(k))]));const evidence=String(fd.get('evidence')||'').trim();if(!evidence||Object.values(scores).some(n=>!Number.isInteger(n)||n<0||n>5)||evalCriteria.some(([k])=>fd.get(k)===''||fd.get(k)===null))return {error:'Informe a evidência e todas as notas entre 0 e 5.'};x.evals.push({agent:String(fd.get('agent')),scores,evidence,comment:String(fd.get('comment')||'').trim(),createdAt:new Date().toISOString()});return {action:'Registrou avaliação: '+person(String(fd.get('agent'))).name}})}
function qualitySection(t){const x=executionOf(t);return `<section class="task-quality"><div class="section-heading"><h3>Um prazo. Todos os repasses.</h3><button class="text-link" data-quality="plan" data-id="${esc(t.id)}">Ajustar plano ${ico('arrow')}</button></div><div class="deadline-contract"><strong>${durationLabel(t.minutes)} de ponta a ponta</strong><p>${x.handoffs.length} repasses ${x.mode==='parallel'?'em paralelo':'em sequência'} · ${x.reviewMinutes} min reservados à revisão.</p>${x.deadlineAt?`<small>Início: ${esc(dateLabel(x.startedAt))}<br>Limite global: ${esc(dateLabel(x.deadlineAt))}</small>`:'<small>Janela ainda não iniciada.</small>'}<button class="btn" data-quality="start" data-id="${esc(t.id)}" ${x.startedAt?'disabled':''}>${ico('clock')}${x.startedAt?'Prazo global registrado':'Registrar início da janela'}</button></div><div class="section-heading"><h3>Avaliações dos agentes</h3><button class="text-link" data-quality="eval" data-id="${esc(t.id)}">Registrar eval ${ico('plus')}</button></div><div class="eval-roster">${[t.director,...t.creators].map(id=>{const p=person(id),evaluations=x.evals.filter(e=>e.agent===id),last=evaluations.at(-1),score=last?(Object.values(last.scores).reduce((a,b)=>a+b,0)/5).toFixed(1):null;return `<div><img src="${personImage(p)}" alt=""><span><strong>${esc(p.name)}</strong><small>${last?`${evaluations.length} avaliação(ões) registrada(s)`:'Ainda sem avaliação'}</small></span><b>${score?`${score}/5`:'—'}</b></div>${last?`<p class="eval-comment">${esc(last.comment||'Sem observação adicional.')}</p>`:''}`}).join('')}</div><p class="quality-note">A entrega só pode ser marcada como concluída com material e avaliação de todos os participantes. As notas são registros de avaliação, não métricas automáticas.</p></section>`}
function qualityExport(t){const x=executionOf(t);return ['## Prazo global e repasses',`Modo: ${x.mode==='parallel'?'paralelo':'sequencial'}. Tempo total: ${durationLabel(t.minutes)}. Reserva de revisão: ${x.reviewMinutes} min.`,x.deadlineAt?`Início: ${x.startedAt}. Limite: ${x.deadlineAt}.`:'O prazo absoluto deve ser estabelecido no início da execução.','Todos os repasses, avaliações e correções precisam terminar antes do prazo global. Se o tempo estiver acabando, a diretora prioriza uma entrega utilizável e declara o restante. Ferramentas pendentes não estendem o prazo sem nova decisão do usuário.',...x.handoffs.map(h=>`### Prompt para ${person(h.agent).name}\nTempo de repasse: ${h.minutes} min\n${h.prompt}`),'## Avaliações registradas',...x.evals.map(e=>`### ${person(e.agent).name}\n${evalCriteria.map(([k,l])=>`${l}: ${e.scores[k]}/5`).join('\n')}\nEvidência: ${e.evidence}\nMelhoria: ${e.comment}\nData: ${e.createdAt}`)].join('\n\n')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-quality]');if(!b)return;const a=b.dataset.quality,id=b.dataset.id;if(a==='plan')qualityForm(id);if(a==='eval')evalForm(id);if(a==='start'){const t=taskById(id),x=executionOf(t);if(!x.startedAt){const conflict=[t.director,...t.creators].map(person).find(p=>studio().tasks.filter(other=>other.id!==t.id&&other.status!=='Entregue'&&other.execution?.startedAt&&Date.parse(other.execution.deadlineAt)>Date.now()&&[other.director,...other.creators].includes(p.id)).length>=(p.capacity||1));if(conflict){toast(conflict.name+' atingiu a capacidade contratada. Aguarde ou ajuste a equipe antes de iniciar.');return}if(x.handoffs.length!==t.creators.length){toast('Configure os repasses e os prompts antes de iniciar a janela.');qualityForm(id);return}x.startedAt=new Date().toISOString();x.deadlineAt=new Date(Date.parse(x.startedAt)+t.minutes*60000).toISOString();persist('Registrou início da janela: '+t.title);taskDetail(id);toast('Prazo global registrado. Isso não inicia agentes automaticamente.')}}if(a==='refresh-prompt'){const f=document.getElementById('studio-form'),t=taskById(b.dataset.task),agent=b.dataset.agent;if(f){if(!confirm('Substituir o texto deste prompt por um novo rascunho com o briefing atual?'))return;f.elements['prompt-'+agent].value=promptFor(t,agent,Number(f.elements['time-'+agent].value)||1);editorDirty=true}}});
